def algorithm(func, dim, lb, ub, budget, rng):
    x = (ub - lb) * rng.uniform(size=dim) + lb
    step_size = 1.0

    for _ in range(budget):
        grad = func.grad(x)
        if grad is None:
            continue

        hessian = np.eye(dim)  # approximate Hessian matrix
        for i in range(dim):
            eps = 1e-6 * rng.uniform()
            dx_i = np.zeros(dim)
            dx_i[i] = eps
            grad_eps = func.grad(x + dx_i)

            if grad_eps is not None:
                hessian[i, i] += (grad_eps - grad[0]) / eps

        # adapt step size based on local curvature
        alpha = 1.0
        for i in range(dim):
            if abs(hessian[i, i]) < 1e-6:
                continue
            d = np.zeros(dim)
            d[i] = 1
            grad_d = func.grad(x + alpha * d)

            if grad_d is not None and hessian[i, i] > 0:
                step_size *= min(1.0, (grad_d[0] - grad[0]) / (alpha * hessian[i, i]))

        x_new = x + step_size * np.array(grad)
        for i in range(dim):
            if x_new[i] < lb or x_new[i] > ub:
                x_new[i] = max(lb, min(ub, x_new[i]))
        x_new = np.clip(x_new, lb, ub)

        # update best solution
        f_new = func(x_new)
        f_best = func(x)

        if f_new < f_best:
            x = x_new

    return x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    def evaluate(x):
        return func(x)

    pop_size = int(np.sqrt(budget))
    max_iter = 1000
    w = 1.2
    c1 = 1.5
    c2 = 2.5
    v = np.random.uniform(-10, 10, (pop_size, dim))

    for i in range(max_iter):
        for j in range(pop_size):
            r1 = rng.randint(0, pop_size)
            r2 = rng.randint(0, pop_size)

            u = w * v[j] + c1 * np.random.uniform(-1, 1) * (v[r1] - v[j]) + \
                c2 * np.random.uniform(-1, 1) * (v[r2] - v[j])

            v[j] = clip(v[j] + u)

        f_values = np.array([evaluate(clip(x)) for x in v])
        idx_sorted = np.argsort(f_values)
        v[idx_sorted[:pop_size//2]] = np.random.uniform(lb, ub, (pop_size//2, dim))

    best_idx = np.argmin(f_values)
